/** Tappable question chips — generated by the agent per listing + conversation (see Panel). */
export default function Starters({ busy, questions, loading, onPick }) {
  return (
    <div hidden={busy} className={`flex shrink-0 flex-wrap gap-1.5 px-3 pb-2.5 ${loading ? 'opacity-50' : ''}`}>
      {questions.map((s) => (
        <button key={s} className="rounded-[14px]" onClick={() => onPick(s)}>
          {s}
        </button>
      ))}
    </div>
  );
}
